class TokenBucket {
  constructor({ capacity, refillPerSecond, now }) {
    if (
      typeof capacity !== 'number' ||
      !Number.isFinite(capacity) ||
      capacity <= 0
    ) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;

    const clockFn = typeof now === 'function' ? now : Date.now;

    // Kapasite kadar başlat
    let tokens = capacity;
    let lastTime = clockFn();
    // Görülen en yüksek zaman (saat geri gidemez)
    let maxTime = lastTime;

    Object.defineProperty(this, '_tokens', { value: () => tokens });
    Object.defineProperty(this, '_lastTime', { value: () => lastTime });
    Object.defineProperty(this, '_maxTime', { value: () => maxTime });

    // Refill: currentTokens() + refill miktarı hesaplar
    const refill = () => {
      const t = clockFn();
      if (t > maxTime) {
        maxTime = t;
        const elapsed = (t - lastTime) / 1000; // saniye
        const added = elapsed * refillPerSecond;
        tokens = Math.min(capacity, tokens + added);
        lastTime = t;
      }
      // Saat geri giderse veya aynı anda çağrılırsa bir şey değişmez
      return tokens;
    };

    Object.defineProperty(this, '_refill', { value: refill });
    Object.defineProperty(this, '_clockFn', { value: clockFn });
  }

  available() {
    const refill = this._refill();
    return refill;
  }

  tryTake(n = 1) {
    if (
      typeof n !== 'number' ||
      !Number.isFinite(n) ||
      n <= 0
    ) {
      throw new RangeError('n must be a positive finite number');
    }

    const tokens = this._refill();

    if (tokens >= n) {
      // tokens'i düşür
      // Private _tokens array'ine erişemiyoruz,
      // tokens değişkenini doğrudan güncellememiz lazım.
      // Ancak tokens local bir değişken. Bunu _tokens array'inde tutmamız lazım.
      // Daha iyi bir yaklaşım: tokens'i private state olarak tutalım.
      // Burayı daha iyi bir yapıyla yeniden yazalım.
    }

    return false;
  }

  msUntil(n = 1) {
    if (
      typeof n !== 'number' ||
      !Number.isFinite(n) ||
      n <= 0
    ) {
      throw new RangeError('n must be a positive finite number');
    }

    if (n > this.capacity) {
      return Infinity;
    }

    if (this.refillPerSecond === 0) {
      const avail = this.available();
      if (avail >= n) {
        return 0;
      }
      return Infinity;
    }

    const avail = this.available();
    if (avail >= n) {
      return 0;
    }

    const needed = n - avail;
    const seconds = needed / this.refillPerSecond;
    const ms = Math.ceil(seconds * 1000);

    return ms;
  }
}

class TokenBucket {
  constructor({ capacity, refillPerSecond, now }) {
    if (
      typeof capacity !== 'number' ||
      !Number.isFinite(capacity) ||
      capacity <= 0
    ) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;

    const clockFn = typeof now === 'function' ? now : Date.now;

    // State: jeton sayısı ve son zaman
    let tokens = capacity;
    let lastRefillTime = clockFn();
    let maxTimeSeen = lastRefillTime;

    const refill = () => {
      const now = clockFn();
      if (now > maxTimeSeen) {
        const elapsed = (now - lastRefillTime) / 1000;
        const added = elapsed * refillPerSecond;
        tokens = Math.min(capacity, tokens + added);
        lastRefillTime = now;
        maxTimeSeen = now;
      }
      return tokens;
    };

    const takeTokens = (n) => {
      tokens -= n;
    };

    // Validate n parameter
    const validateN = (n, label = 'n') => {
      if (
        typeof n !== 'number' ||
        !Number.isFinite(n) ||
        n <= 0
      ) {
        throw new RangeError(label + ' must be a positive finite number');
      }
    };

    Object.defineProperties(this, {
      available: {
        value: function () {
          return refill();
        },
        enumerable: false,
        writable: false,
      },
      tryTake: {
        value: function tryTake(n = 1) {
          validateN(n);
          const current = refill();
          if (current >= n) {
            takeTokens(n);
            return true;
          }
          return false;
        },
        enumerable: false,
        writable: false,
      },
      msUntil: {
        value: function msUntil(n = 1) {
          validateN(n);

          if (n > this.capacity) {
            return Infinity;
          }

          if (this.refillPerSecond === 0) {
            const avail = refill();
            if (avail >= n) {
              return 0;
            }
            return Infinity;
          }

          const avail = refill();
          if (avail >= n) {
            return 0;
          }

          const needed = n - avail;
          const seconds = needed / this.refillPerSecond;
          const ms = Math.ceil(seconds * 1000);

          return ms;
        },
        enumerable: false,
        writable: false,
      },
    });
  }
}

module.exports = { TokenBucket };

