const { TokenBucket } = require('./kova.js');

let testsPassed = 0;
let testsFailed = 0;

function assert(condition, msg) {
  if (condition) {
    testsPassed++;
    console.log('  PASS:', msg);
  } else {
    testsFailed++;
    console.log('  FAIL:', msg);
  }
}

// ---- Test 1: Basic creation & initial available ----
console.log('\n--- Test 1: Basic creation ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: fakeNow });
  assert(b.available() === 10, 'initial available() === 10');
}

// ---- Test 2: tryTake succeeds ----
console.log('\n--- Test 2: tryTake ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: fakeNow });
  assert(b.tryTake(3) === true, 'tryTake(3) returns true');
  assert(b.available() <= 8, 'available drops after take');
}

// ---- Test 3: tryTake insufficient ----
console.log('\n--- Test 3: tryTake insufficient ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: fakeNow });
  assert(b.tryTake(11) === false, 'tryTake(11) returns false');
  assert(b.available() > 0, 'tokens not deducted on failed take');
}

// ---- Test 4: Refill over time ----
console.log('\n--- Test 4: Refill ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
  b.tryTake(10); // drain
  assert(b.available() === 0, 'available === 0 after draining');
  t = 1000; // 1 second later
  const avail = b.available();
  assert(Math.abs(avail - 10) < 0.001, 'refills to ~10 after 1s at 10/s (got ' + avail + ')');
}

// ---- Test 5: Partial refill ----
console.log('\n--- Test 5: Partial refill ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
  b.tryTake(10);
  t = 500; // 0.5s → 5 tokens
  const avail = b.available();
  assert(Math.abs(avail - 5) < 0.001, 'partial refill after 500ms at 10/s (got ' + avail + ')');
}

// ---- Test 6: msUntil ----
console.log('\n--- Test 6: msUntil ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
  assert(b.msUntil(1) === 0, 'msUntil(1) === 0 when sufficient');

  b.tryTake(10);
  const ms2 = b.msUntil(1);
  assert(ms2 === 100, 'msUntil(1) === 100 when 10/s (got ' + ms2 + ')');

  assert(b.msUntil(11) === Infinity, 'msUntil(11) === Infinity (n > capacity)');
}

// ---- Test 7: refillPerSecond = 0 ----
console.log('\n--- Test 7: Zero refill rate ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 0, now: fakeNow });
  assert(b.msUntil(1) === 0, 'msUntil(1) === 0 when enough tokens');
  b.tryTake(10);
  assert(b.msUntil(1) === Infinity, 'msUntil(1) === Infinity when 0 refill rate');
}

// ---- Test 8: Clock going backwards ----
console.log('\n--- Test 8: Clock backwards ---');
{
  let t = 1000;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
  // Construction at t=1000
  t = 2000;
  b.available(); // refill at t=2000 (1s elapsed, 10 tokens)
  t = 1500; // go back
  const afterBack = b.available();
  assert(afterBack <= 10, 'clock backwards should not add tokens (got ' + afterBack + ')');
  assert(afterBack <= 10.5, 'tokens should not increase going back');
}

// ---- Test 9: Clock goes forward after back ----
console.log('\n--- Test 9: Forward after back ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
  t = 1000;
  b.available(); // refill at t=1000
  t = 500; // go back
  b.available(); // no refill
  t = 3000; // go forward 2s from max (2000)
  const avail = b.available();
  assert(Math.abs(avail - 10) < 0.001, 'forward after back caps at capacity (got ' + avail + ')');
}

// ---- Test 10: RangeError on invalid n ----
console.log('\n--- Test 10: RangeError on n ---');
{
  let t = 0;
  const fakeNow = () => t;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: fakeNow });

  try { b.tryTake(0); assert(false, 'tryTake(0) should throw'); } catch(e) { assert(e instanceof RangeError, 'tryTake(0) throws RangeError'); }
  try { b.tryTake(-1); assert(false, 'tryTake(-1) should throw'); } catch(e) { assert(e instanceof RangeError, 'tryTake(-1) throws RangeError'); }
  try { b.tryTake(NaN); assert(false, 'tryTake(NaN) should throw'); } catch(e) { assert(e instanceof RangeError, 'tryTake(NaN) throws RangeError'); }
  try { b.tryTake(Infinity); assert(false, 'tryTake(Infinity) should throw'); } catch(e) { assert(e instanceof RangeError, 'tryTake(Infinity) throws RangeError'); }
  try { b.msUntil(0); assert(false, 'msUntil(0) should throw'); } catch(e) { assert(e instanceof RangeError, 'msUntil(0) throws RangeError'); }
  try { b.msUntil(NaN); assert(false, 'msUntil(NaN) should throw'); } catch(e) { assert(e instanceof RangeError, 'msUntil(NaN) throws RangeError'); }
}

// ---- Test 11: RangeError on capacity ----
console.log('\n--- Test 11: RangeError on capacity ---');
{
  try { new TokenBucket({ capacity: -1, refillPerSecond: 1 }); assert(false, '-1 capacity should throw'); } catch(e) { assert(e instanceof RangeError, 'capacity=-1 throws RangeError'); }
  try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); assert(false, '0 capacity should throw'); } catch(e) { assert(e instanceof RangeError, 'capacity=0 throws RangeError'); }
  try { new TokenBucket({ capacity: Infinity, refillPerSecond: 1 }); assert(false, 'Infinity capacity should throw'); } catch(e) { assert(e instanceof RangeError, 'capacity=Infinity throws RangeError'); }
  try { new TokenBucket({ capacity: NaN, refillPerSecond: 1 }); assert(false, 'NaN capacity should throw'); } catch(e) { assert(e instanceof RangeError, 'capacity=NaN throws RangeError'); }
}

